local GlassYokeMaker = {}
local PRODUCTS = {
    iron_glassyoke = { name = "Železni jarem za prenos stekla", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni jarem za prenos stekla za steklarje." },
    bronze_glassyoke = { name = "Bronast jarem za prenos stekla", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast jarem za prenos stekla za steklarje." },
    silver_glassyoke = { name = "Srebrn jarem za prenos stekla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn jarem za prenos stekla za steklarje." },
    gilded_glassyoke = { name = "Pozlačen jarem za prenos stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen jarem za prenos stekla za steklarje." },
    jewel_set_glassyoke = { name = "Draguljast jarem za prenos stekla", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast jarem za prenos stekla za steklarje." },
    royal_sovereign_glassyoke = { name = "Kraljevski suveren jarem za prenos stekla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren jarem za prenos stekla z biseri za krono." },
}
local BUILDINGS = {
    glassyoke_workshop = { name = "Glassyoke delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassyoke_house = { name = "Glassyoke hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassyoke_atelier = { name = "Mojstrski glassyoke atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassyoke_palace = { name = "Suverena glassyoke palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassYokeMaker.ironStock=14; GlassYokeMaker.bronzeStock=12; GlassYokeMaker.woodStock=14; GlassYokeMaker.leatherStock=10; GlassYokeMaker.silverStock=8; GlassYokeMaker.goldStock=6; GlassYokeMaker.jewelStock=4; GlassYokeMaker.pearlStock=4
GlassYokeMaker.productStock = {}; GlassYokeMaker.buildings = {}; GlassYokeMaker.maker = nil; GlassYokeMaker.activeMaking = {}; GlassYokeMaker.totalProducts = 0; GlassYokeMaker.dayTimer = 0
function GlassYokeMaker.init() GlassYokeMaker.ironStock=14; GlassYokeMaker.bronzeStock=12; GlassYokeMaker.woodStock=14; GlassYokeMaker.leatherStock=10; GlassYokeMaker.silverStock=8; GlassYokeMaker.goldStock=6; GlassYokeMaker.jewelStock=4; GlassYokeMaker.pearlStock=4; GlassYokeMaker.productStock={}; GlassYokeMaker.buildings={}; GlassYokeMaker.maker=nil; GlassYokeMaker.activeMaking={}; GlassYokeMaker.totalProducts=0; GlassYokeMaker.dayTimer=0; print("[GlassYokeMaker] Royal Glass Yoke Maker System initialized (6 products, 4 buildings)") end
function GlassYokeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassYokeMaker.maker={name=n or ("Jarmar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jarmar najet: %s (spretnost: %d)",GlassYokeMaker.maker.name,s),"success") end; return true end
function GlassYokeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassYokeMaker.build(id) local ok,e=GlassYokeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassYokeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassYokeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassYokeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassYokeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassYokeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassYokeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassYokeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassYokeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassYokeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassYokeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassYokeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassYokeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassYokeMaker.buildings==0 then return false,"Potrebna jarmna delavnica" end; if not GlassYokeMaker.maker then return false,"Potreben jarmar" end; return true end
function GlassYokeMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassYokeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassYokeMaker.ironStock=GlassYokeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassYokeMaker.bronzeStock=GlassYokeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassYokeMaker.woodStock=GlassYokeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassYokeMaker.leatherStock=GlassYokeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassYokeMaker.silverStock=GlassYokeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassYokeMaker.goldStock=GlassYokeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassYokeMaker.jewelStock=GlassYokeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassYokeMaker.pearlStock=GlassYokeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassYokeMaker.maker then t=math.max(1,t-math.floor(GlassYokeMaker.maker.skill/13)) end; table.insert(GlassYokeMaker.activeMaking,{id="glassyoke_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassYokeMaker.completeMaking(m) local q=1.0+(GlassYokeMaker.getQualityBonus()/100); if GlassYokeMaker.maker then q=q+(GlassYokeMaker.maker.skill/140) end; q=math.min(2.5,q); GlassYokeMaker.productStock[m.productType]=(GlassYokeMaker.productStock[m.productType] or 0)+m.quantity; GlassYokeMaker.totalProducts=GlassYokeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassYokeMaker.maker then GlassYokeMaker.maker.itemsMade=GlassYokeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassYokeMaker.maker.skill=math.min(100,GlassYokeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jarem izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassyoke.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassYokeMaker.update(dt) if not _G.state then return end; GlassYokeMaker.dayTimer=GlassYokeMaker.dayTimer+dt; if GlassYokeMaker.dayTimer>=30 then GlassYokeMaker.dayTimer=0; for i=#GlassYokeMaker.activeMaking,1,-1 do local m=GlassYokeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassYokeMaker.completeMaking(m); table.remove(GlassYokeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassYokeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassYokeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassYokeMaker.getStats() return {ironStock=GlassYokeMaker.ironStock,bronzeStock=GlassYokeMaker.bronzeStock,woodStock=GlassYokeMaker.woodStock,leatherStock=GlassYokeMaker.leatherStock,silverStock=GlassYokeMaker.silverStock,goldStock=GlassYokeMaker.goldStock,jewelStock=GlassYokeMaker.jewelStock,pearlStock=GlassYokeMaker.pearlStock,productStock=GlassYokeMaker.productStock,numBuildings=#GlassYokeMaker.buildings,hasMaker=GlassYokeMaker.maker~=nil,makerName=GlassYokeMaker.maker and GlassYokeMaker.maker.name or "—",makerSkill=GlassYokeMaker.maker and GlassYokeMaker.maker.skill or 0,activeMaking=#GlassYokeMaker.activeMaking,totalProducts=GlassYokeMaker.totalProducts} end
return GlassYokeMaker
